const crypto = require('crypto');

const secret = process.env.LENDLOOP_API_SECRET || process.env.N8N_API_SECRET || 'CHANGE_ME_N8N_API_SECRET';
const timestamp = Math.floor(Date.now() / 1000).toString();
const method = 'GET';
const path = '/overdue-loans?limit=100';
const rawBody = '';

const canonical = `${timestamp}.${method}.${path}.${rawBody}`;
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');

const baseUrl = process.env.CONVEX_SITE_URL || 'http://host.docker.internal:3211';

return [{
  json: {
    url: `${baseUrl}${path}`,
    headers: {
      'Content-Type': 'application/json',
      'X-LL-Timestamp': timestamp,
      'X-LL-Signature': signature
    }
  }
}];

const response = $input.first().json;
const loans = Array.isArray(response.loans) ? response.loans : [];

if (loans.length === 0) {
  return [];
}

const today = new Date().toISOString().slice(0, 10);

return loans.map((loan) => ({
  json: {
    loanId: loan.loanId,
    toolName: loan.toolName,
    dueDate: loan.dueDate,
    daysOverdue: loan.daysOverdue,
    borrowerEmail: loan.borrower ? loan.borrower.email : 'neighbor@example.com',
    borrowerName: loan.borrower ? loan.borrower.name : 'Neighbor',
    runDate: today,
    idempotencyKey: `${loan.loanId}:${today}`
  }
}));

const item = $input.first().json;
return [{
  json: {
    ...item,
    emailNotification: {
      to: item.borrowerEmail,
      subject: `[LendLoop Reminder] Return tool: ${item.toolName}`,
      body: `Hi ${item.borrowerName},\n\nThis is a friendly reminder that your loan for ${item.toolName} was due on ${item.dueDate} (${item.daysOverdue} days overdue).\n\nPlease return it to the owner as soon as possible so other neighbors can use it.`
    }
  }
}];

const crypto = require('crypto');

const secret = process.env.LENDLOOP_API_SECRET || process.env.N8N_API_SECRET || 'CHANGE_ME_N8N_API_SECRET';
const item = $input.first().json;

const timestamp = Math.floor(Date.now() / 1000).toString();
const method = 'POST';
const path = '/reminder-result';

const payload = {
  contractVersion: 'v1',
  idempotencyKey: item.idempotencyKey,
  loanId: item.loanId,
  status: 'sent',
  channel: 'email',
  sentAt: new Date().toISOString(),
  error: null
};

const rawBody = JSON.stringify(payload);
const canonical = `${timestamp}.${method}.${path}.${rawBody}`;
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
const baseUrl = process.env.CONVEX_SITE_URL || 'http://host.docker.internal:3211';

return [{
  json: {
    url: `${baseUrl}${path}`,
    body: payload,
    rawBody,
    headers: {
      'Content-Type': 'application/json',
      'X-LL-Timestamp': timestamp,
      'X-LL-Signature': signature
    }
  }
}];
